from dataclasses import dataclass, field
from datetime import datetime
from typing import Literal

Decision = Literal["AUTO_APPROVE", "REJECT", "MANUAL_REVIEW", "REQUEST_DOCS"]


@dataclass
class Line:
    type: str  # 'medical' | 'dental' | 'vision' | 'accident'
    amount: float
    docs: list[str] = field(default_factory=list)
    pre_auth_id: str | None = None
    emergency: bool = False
    fraud_flag: bool = False


@dataclass
class Claim:
    lines: list[Line]


@dataclass
class Policyholder:
    plan_tier: str
    region: str
    policy_active: bool
    recent_approved_claims: list[datetime] = field(default_factory=list)
    deductible_remaining: float = 0.0


@dataclass
class PolicyConfig:
    high_cost_regions: set[str] = field(default_factory=set)
    required_docs: dict[str, tuple[str, ...]] = field(default_factory=lambda: {
        "medical": ("invoice", "diagnosis"),
        "dental": ("invoice",),
        "vision": ("invoice",),
        "accident": ("invoice", "police_report"),
    })
    copay_medical: float = 25.0


@dataclass
class Outcome:
    decision: Decision
    reason: str
    reimbursement_amount: float = 0.0
    deductible_applied: float = 0.0
    copay_applied: float = 0.0
    cap_applied: bool = False
