"""Declarative rules. Each rule returns an Outcome to short-circuit,
or None to pass. Add a rule = write a function and append it to RULES."""

from datetime import datetime, timedelta

from .models import Claim, Outcome, Policyholder, PolicyConfig


def policy_inactive(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    if not h.policy_active:
        return Outcome("REJECT", "POLICY_INACTIVE")
    return None


def fraud_flag(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    if any(l.fraud_flag for l in claim.lines):
        return Outcome("MANUAL_REVIEW", "FRAUD_FLAG")
    return None


def high_frequency(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    window = now - timedelta(days=30)
    if sum(1 for d in h.recent_approved_claims if d >= window) > 3:
        return Outcome("MANUAL_REVIEW", "HIGH_FREQUENCY")
    return None


def dental_tier(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    if any(l.type == "dental" for l in claim.lines) and h.plan_tier not in ("premium", "elite"):
        return Outcome("REJECT", "NOT_COVERED")
    return None


def pre_auth_required(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    for l in claim.lines:
        if l.type == "medical" and l.amount > 500 and not l.pre_auth_id and not l.emergency:
            return Outcome("REQUEST_DOCS", "PRE_AUTH_REQUIRED")
    return None


def missing_docs(claim: Claim, h: Policyholder, c: PolicyConfig, now: datetime) -> Outcome | None:
    for l in claim.lines:
        required = c.required_docs.get(l.type, ())
        if any(d not in l.docs for d in required):
            return Outcome("REQUEST_DOCS", "MISSING_DOCS")
    return None


# Order matters — first match wins.
RULES = [
    policy_inactive,
    fraud_flag,
    high_frequency,
    dental_tier,
    pre_auth_required,
    missing_docs,
]


def vision_override(claim: Claim, h: Policyholder, c: PolicyConfig) -> Outcome | None:
    """Special-cased before the normal pipeline. Single low-amount vision
    claim with docs auto-approves regardless of other checks."""
    if not (len(claim.lines) == 1
            and claim.lines[0].type == "vision"
            and claim.lines[0].amount < 200):
        return None
    if any(d not in claim.lines[0].docs for d in c.required_docs.get("vision", ())):
        return None
    if not h.policy_active:
        return Outcome("REJECT", "POLICY_INACTIVE")
    return Outcome("AUTO_APPROVE", "VISION_OVERRIDE",
                   reimbursement_amount=claim.lines[0].amount)
