from datetime import datetime, timezone

from .models import Claim, Outcome, Policyholder, PolicyConfig
from .rules import RULES, vision_override


def evaluate_claim(
    claim: Claim,
    holder: Policyholder,
    config: PolicyConfig,
    now: datetime | None = None,
) -> Outcome:
    now = now or datetime.now(timezone.utc)

    if (out := vision_override(claim, holder, config)) is not None:
        return out

    for rule in RULES:
        if (out := rule(claim, holder, config, now)) is not None:
            return out

    return _compute_reimbursement(claim, holder, config)


def _compute_reimbursement(claim: Claim, holder: Policyholder, config: PolicyConfig) -> Outcome:
    subtotal = sum(l.amount for l in claim.lines)
    copay = sum(config.copay_medical for l in claim.lines if l.type == "medical")
    after_copay = max(0.0, subtotal - copay)
    deductible = min(holder.deductible_remaining, after_copay)
    final = after_copay - deductible

    cap_applied = False
    if holder.region in config.high_cost_regions:
        capped = subtotal * 0.80
        if final > capped:
            final = capped
            cap_applied = True

    return Outcome(
        "AUTO_APPROVE", "APPROVED",
        reimbursement_amount=final,
        deductible_applied=deductible,
        copay_applied=copay,
        cap_applied=cap_applied,
    )
